using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Common.Exceptions;using OAS.Contracts.Accounting.EmployeeAccounts;using OAS.Domain.Accounting.Entities;using OAS.Domain.Features.Employees.Entities;
namespace OAS.Application.Accounting.EmployeeAccounts.Queries.GetEmployeeAccountById;public sealed class GetEmployeeAccountByIdQueryHandler(IReadRepository<EmployeeAccount,Guid> repository,IReadRepository<Employee,Guid> employees,IReadRepository<Account,Guid> accounts):IRequestHandler<GetEmployeeAccountByIdQuery,EmployeeAccountDto>{public async Task<EmployeeAccountDto> Handle(GetEmployeeAccountByIdQuery r,CancellationToken ct){var m=await repository.GetByIdAsync(r.Id,ct)??throw new NotFoundException(nameof(EmployeeAccount),r.Id);var e=await employees.GetByIdAsync(m.EmployeeId,ct)??throw new NotFoundException(nameof(Employee),m.EmployeeId);var a=await accounts.GetByIdAsync(m.AccountId,ct)??throw new NotFoundException(nameof(Account),m.AccountId);return new(m.Id,m.EmployeeId,e.EmployeeCode,e.DisplayName,m.AccountId,a.Code,a.NameAr,m.IsActive,Convert.ToBase64String(m.RowVersion));}}
